#!/usr/bin/env bash
set -euo pipefail

SRC="/workspaces/Photon-Camera-fresh-iris"
OUTDIR="$SRC/fresh_iris_outputs"
BRANCH="experimental-clean-photon-rebuild"
EXPECTED_HEAD_SHORT="aac8ea5a"
STAMP="$(date +%Y%m%d_%H%M%S)"
NEW_VERSION="0.9726432"
NEW_BUILD="26432"

fail() { echo "FAIL: $*" >&2; exit 1; }
sha() { sha256sum "$1" | awk '{print toupper($1)}'; }

cd "$SRC" || fail "Missing active Codespace: $SRC"
mkdir -p "$OUTDIR"

[[ -f local.properties ]] || fail "local.properties missing; restore Android SDK pointer first"
grep -q '^sdk\.dir=' local.properties || fail "local.properties lacks sdk.dir"

HDRX="app/src/main/java/com/particlesdevs/photoncamera/processing/processor/HdrxProcessor.java"
