RECON="app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java"
ALIGN="app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2Alignment.java"
INPUT="app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2CfaInput.java"
DINIT="app/src/main/assets/shaders/motionv2/direct_rgb_init.glsl"
DACC="app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl"
