declare -A BASE
BASE['app/src/main/assets/shaders/motionv2/direct_rgb_init.glsl']='8E0D3A176280C49D17094BC318382F9C1AF97C76FFFA85ACA7B19053F516C5C1'
BASE['app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl']='A7BF945D386C881A9259A9626D2A7F69AE8A5DA998387248D484D91B9A50E221'
