BASE['app/src/main/assets/shaders/motionv2/render.glsl']='3CFEFFAC559DE25403C49C1B3A45BDE56E8D9CA3042A74B54204E1BEC0B603D9'
BASE['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2ColorTransform.java']='FA08A31B10C4801BF12C76BD2AE9371ED920CC08AD6C7A5F781BB7F9219781A2'
BASE['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Denoise.java']='E36C9CF5BE696A6B9F20DB1DA8585283EF72FB34D4A55D85233D3987F57DEE9B'
BASE['app/src/main/assets/shaders/motionv2/color_transform.glsl']='7568832F32C701D7E1F2D7F56E5B5BE7C8A8CF2B46D307478322E1824DE8AFFF'
BASE['app/src/main/assets/shaders/motionv2/denoise.glsl']='3C4BB26080FD50DFEF4656A03F7EFC6171A1F791E77EDF0A36863AECE299720E'
BASE['app/version.properties']='053E495F9A6C7AA301B83E3DF3BD1896307CF883E168A6384BC855210FFDD5CF'
BASE['app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java']='76CAC4E7FE2B185068ADE3F34D5BB04FA60E81FFF3E05D3027897501A9764874'
BASE['app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2Alignment.java']='80548631423555C5C104A76E5B5950FFB44C69008D85D47440C8E01D7A0B2BA8'
BASE['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/PostPipeline.java']='17409FE5322F5F83DEE3159D7E54F9810A897C3D86DAF4F0A0F3692122D4D96A'
