FIXHASH['app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl']='9E2643D9AD35BF632E328D33E467BE84F7C5C902BC7F3C3C8A39B95D6F8D903C'
FIXHASH['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Render.java']='C09A2BF605DA61B0629AC6B6F83C03FAEAF30B144A4DB3EA7A9B4644596DF709'
FIXHASH['app/src/main/assets/shaders/motionv2/render.glsl']='BC29D7B12B1E57BEC4EAB2FED28F61853E65A9352D2B6CD965879B92A598EACA'
FIXHASH['app/src/main/assets/shaders/motionv2/gainmap.glsl']='7B562A9B2F8445374F0349069802B16602B46E6E60CCEC4F59E24F17CDB8DC45'
FIXHASH['app/src/main/java/com/particlesdevs/photoncamera/processing/ultrahdr/MotionV2UltraHdr.java']='6583B31CE9728947EA81B0A0CB51746384BF969A7811EF1A6B888FE2F6DA9FA0'
FIXHASH['app/version.properties']='AC9A3840EBD7C7FD7CD1FE44FD0FEB693C5C994CA3C9B77F6E5D49221A75AFA7'

