FIXB64['app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl']=''
FIXB64['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Render.java']=''
FIXB64['app/src/main/assets/shaders/motionv2/render.glsl']=''
FIXB64['app/src/main/assets/shaders/motionv2/gainmap.glsl']=''
FIXB64['app/src/main/java/com/particlesdevs/photoncamera/processing/ultrahdr/MotionV2UltraHdr.java']=''
FIXB64['app/version.properties']='I1dlZCBBdWcgMDUgMjI6NTY6MDQgRURUIDIwMjYKVkVSU0lPTl9OQU1FPTAuOTcyNjQzMgpWRVJTSU9OX0JVSUxEPTI2NDMyCg=='

echo "======================================================================"
echo "26432 - STACK-SIZE-INVARIANT MERGE + TRUE V2 ULTRA HDR"
echo "======================================================================"

echo "=== GATE 0: EXACT 26431 VISUAL / SOURCE LINEAGE ==="
[[ "$(git branch --show-current)" == "$BRANCH" ]] || fail "Wrong branch"
[[ "$(git rev-parse --short=8 HEAD)" == "$EXPECTED_HEAD_SHORT" ]] || \
  fail "Expected committed base $EXPECTED_HEAD_SHORT, got $(git rev-parse --short=8 HEAD)"

for rel in "${!BASE[@]}"; do
  [[ -f "$rel" ]] || fail "Missing 26431 lineage file: $rel"
  [[ "$(sha "$rel")" == "${BASE[$rel]}" ]] || fail "26431 hash mismatch: $rel"
done

grep -q 'IRIS_26431_MOTION_V2_ALL_FRAME_HANDOFF' "$HDRX" || fail "26431 all-frame handoff missing"
grep -q 'targetFraction=1.0' "$HDRX" || fail "26431 all-frame telemetry missing"
grep -q 'globalGyroDiscard=false' "$HDRX" || fail "26431 global discard bypass missing"
grep -q 'saveBitmapAsJPGSdrOnly' "$HDRX" || fail "26431 Motion JPEG route missing"
grep -q 'IRIS_26431_MOTION_V2_HONEST_SDR_JPEG' "$IMAGESAVER" || fail "26431 Motion JPEG helper missing"
grep -q 'IRIS_26431_MOTION_V2_COLOR_AND_LENS_SHADING_OWNER' "$COLORJ" || fail "26431 color owner missing"
grep -q 'IRIS_26431_SENSOR_CLIP_THEN_LENS_SHADING_COLOR_OWNER' "$COLORG" || fail "26431 color shader missing"
grep -q 'IRIS_26431_MINIMAL_SUPPORT_OWNED_RESIDUAL_CLEANUP' "$DENOISEG" || fail "26431 denoise missing"
grep -q 'IRIS_26431_BODY_PRESERVING_HDR_TO_SDR' "$RENDERG" || fail "26431 tone missing"

grep -q 'IRIS_26429_SHARED_GUIDE_ROBUSTNESS_REFERENCE_STRUCTURE' "$DACC" || fail "26429 edge fix missing"
grep -q 'rgbPredictionRobustness=false' "$RECON" || fail "26429 robustness architecture missing"
grep -q 'referenceCfaStructure=' "$RECON" || fail "26429 reference structure missing"
grep -q 'exposureFusion=false esd=false ablc=false' "$POST" || fail "V2 legacy bypass missing"
grep -q 'initial=false autoExposure=false' "$POST" || fail "V2 Initial/AutoExposure bypass missing"
grep -q 'captureSharpening=false correctingFlow=false sharpen2=false' "$POST" || fail "V2 sharpen bypass missing"

[[ -f "$OLDUHDR" ]] || fail "Photo/Night UltraHdrSaver missing"
OLDUHDR_HASH="$(sha "$OLDUHDR")"
grep -q 'UltraHdrSaver.save' "$IMAGESAVER" || fail "Photo/Night Ultra HDR path missing"

echo "PASS: 26431 exposure/color/tone + 26429 color-edge fix + V2 isolation proven"

echo "=== GATE 1: BACKUP BRANCH + PRE-EDIT BINARY PATCH ==="
SAFETY="$OUTDIR/safety_26432_stack_robust_true_ultrahdr_$STAMP"
CAND="$SAFETY/candidate"
ORIG="$SAFETY/originals"
mkdir -p "$CAND" "$ORIG"

BACKUP="backup/codespace-before-26432-stack-robust-true-ultrahdr-$STAMP"
git branch "$BACKUP"
PREPATCH="$SAFETY/pre_26432_working_tree.patch"
git diff --binary HEAD -- app > "$PREPATCH"

TARGETS=(
  "$DINIT" "$DACC" "$RENDERJ" "$RENDERG" "$GAINMAPG"
  "$POST" "$V2UHDR" "$HDRX" "$IMAGESAVER" "$VERSION"
)

for rel in "${TARGETS[@]}"; do
  if [[ -e "$rel" ]]; then
    mkdir -p "$ORIG/$(dirname "$rel")"
    cp -a "$rel" "$ORIG/$rel"
  fi
done

PROTECTED_BEFORE="$SAFETY/protected_hashes_before.txt"
PROTECTED_AFTER="$SAFETY/protected_hashes_after.txt"
hash_protected() {
  local out="$1"
  : > "$out"
  while IFS= read -r -d '' f; do
    skip=0
    for t in "${TARGETS[@]}"; do [[ "$f" == "$t" ]] && skip=1 && break; done
    [[ "$skip" -eq 1 ]] && continue
    printf '%s  %s\n' "$(sha "$f")" "$f" >> "$out"
  done < <(git ls-files -z app)
  sort -o "$out" "$out"
}
hash_protected "$PROTECTED_BEFORE"

echo "=== GATE 2: BUILD COMPLETE TEMPORARY CANDIDATES ==="
for rel in "${!FIXB64[@]}"; do
  dst="$CAND/$rel"
  mkdir -p "$(dirname "$dst")"
  printf '%s' "${FIXB64[$rel]}" | base64 -d > "$dst"
  [[ "$(sha "$dst")" == "${FIXHASH[$rel]}" ]] || fail "Candidate hash mismatch: $rel"
done

for rel in "$POST" "$HDRX" "$IMAGESAVER"; do
  mkdir -p "$CAND/$(dirname "$rel")"
  cp -a "$rel" "$CAND/$rel"
done

TRANSFORM="$SAFETY/transform_26432.py"
cat > "$TRANSFORM" <<'PYTRANS'
from pathlib import Path
import sys

post=Path(sys.argv[1]); hdrx=Path(sys.argv[2]); img=Path(sys.argv[3])

def once(s,old,new,label):
    n=s.count(old)
    if n != 1:
        raise SystemExit(f"FAIL: {label} expected once, found {n}")
    return s.replace(old,new,1)

s=post.read_text()
s=once(
    s,
    'import com.particlesdevs.photoncamera.processing.render.Parameters;',
    'import com.particlesdevs.photoncamera.processing.render.Parameters;\n'
    'import com.particlesdevs.photoncamera.processing.ultrahdr.MotionV2UltraHdr;',
    'PostPipeline UltraHDR import')
s=once(
    s,
    '    public ByteBuffer motionV2FloatCfa;',
    '''    public ByteBuffer motionV2FloatCfa;

    /* IRIS_26432_TRUE_V2_GAINMAP_HANDOFF */
    public Bitmap motionV2GainMapBitmap;
    public float motionV2GainMapMaxRatio = 1.0f;''',
    'PostPipeline gainmap fields')
s=once(
    s,
    '''        GLImage resImg = runAll();
        Bitmap res = resImg.getBufferedImage();
        Allocator.free(resImg.byteBuffer);
        GLTexture.closeAll();
        return res;''',
    '''        GLImage resImg = runAll();
        Bitmap res = resImg.getBufferedImage();

        /*
         * IRIS_26432_TRUE_V2_ULTRAHDR_ATTACH
         * Gain map came from pre-tone extended-linear Motion V2 signal.
         */
        if (mParameters.motionV2Active && motionV2GainMapBitmap != null) {
            boolean attached = MotionV2UltraHdr.attach(
                    res,
                    motionV2GainMapBitmap,
                    getRotation(),
                    motionV2GainMapMaxRatio);
            try {
                com.particlesdevs.photoncamera.util.MotionTrace.processingState(
                        "IRIS_26432_TRUE_V2_ULTRAHDR",
                        "attached=" + attached
                                + " source=extendedLinearPreTone"
                                + " sdrBasePreserved=true"
                                + " bodyGainUnity=true"
                                + " maxRatio=" + motionV2GainMapMaxRatio);
            } catch (Throwable ignored) {}
            motionV2GainMapBitmap = null;
        }

        Allocator.free(resImg.byteBuffer);
        GLTexture.closeAll();
        return res;''',
    'PostPipeline gainmap attach')
post.write_text(s)

s=hdrx.read_text()
if 'IRIS_26431_MOTION_V2_ALL_FRAME_HANDOFF' not in s:
    raise SystemExit('FAIL: Hdrx is not 26431 all-frame baseline')
s=once(s,'saveBitmapAsJPGSdrOnly(','saveBitmapAsJPGMotionV2(','Hdrx Motion JPEG helper')
s=s.replace('IRIS_26431_MOTION_V2_NO_SYNTHETIC_BITMAP_GAINMAP',
            'IRIS_26432_MOTION_V2_TRUE_LINEAR_GAINMAP')
s=s.replace(
    '"syntheticBitmapGainMap=false"\n'
    '                            + " sdrJpeg=true"\n'
    '                            + " trueV2GainMapPending=true"',
    '"syntheticBitmapGainMap=false"\n'
    '                            + " sdrBase=true"\n'
    '                            + " trueV2LinearGainMap=true"\n'
    '                            + " bodyGainUnity=true"')
hdrx.write_text(s)

s=img.read_text()
if 'IRIS_26431_MOTION_V2_HONEST_SDR_JPEG' not in s:
    raise SystemExit('FAIL: ImageSaver is not 26431 baseline')
s=once(s,'saveBitmapAsJPGSdrOnly(','saveBitmapAsJPGMotionV2(','ImageSaver Motion helper')
s=s.replace('IRIS_26431_MOTION_V2_HONEST_SDR_JPEG',
            'IRIS_26432_MOTION_V2_DIRECT_GAINMAP_JPEG')
s=s.replace('SDR-only','Motion-V2 direct')
img.write_text(s)
PYTRANS
python3 "$TRANSFORM" "$CAND/$POST" "$CAND/$HDRX" "$CAND/$IMAGESAVER"

CINIT="$CAND/$DINIT"; CACC="$CAND/$DACC"
CRJ="$CAND/$RENDERJ"; CRG="$CAND/$RENDERG"
CGM="$CAND/$GAINMAPG"; CUHDR="$CAND/$V2UHDR"
CPOST="$CAND/$POST"; CHDRX="$CAND/$HDRX"; CIMG="$CAND/$IMAGESAVER"
CV="$CAND/$VERSION"

echo "=== GATE 2A: PREVIOUS-BEHAVIOR COMPATIBILITY PROOF ==="
[[ "$(sha "$COLORJ")" == "${BASE[$COLORJ]}" ]] || fail "26431 color Java changed"
[[ "$(sha "$COLORG")" == "${BASE[$COLORG]}" ]] || fail "26431 color shader changed"
[[ "$(sha "$DENOISEJ")" == "${BASE[$DENOISEJ]}" ]] || fail "26431 denoise Java changed"
[[ "$(sha "$DENOISEG")" == "${BASE[$DENOISEG]}" ]] || fail "26431 denoise shader changed"

grep -q 'IRIS_26432_26431_TONE_PRESERVED_MINUS_032EV' "$CRG" || fail "26431 tone-preservation marker missing"
grep -q 'const float bodyStart=0.65;' "$CRG" || fail "26431 body start changed"
grep -q 'const float logShape=3.0;' "$CRG" || fail "26431 highlight shape changed"
grep -q 'linearSrgb\*=outputExposureScale;' "$CRG" || fail "0.80 linear post-tone scale missing"
grep -q 'OUTPUT_EXPOSURE_SCALE = 0.80f' "$CRJ" || fail "0.80 render scale missing"
grep -q 'outputExposureEv=-0.321928' "$CRJ" || fail "-0.322EV telemetry missing"

grep -q 'IRIS_26431_MOTION_V2_ALL_FRAME_HANDOFF' "$CHDRX" || fail "All-frame Motion handoff lost"
grep -q 'targetFraction=1.0' "$CHDRX" || fail "All-frame target lost"
grep -q 'globalGyroDiscard=false' "$CHDRX" || fail "Global Motion discard returned"

grep -q 'IRIS_26432_REFERENCE_SUPPORT_ANCHOR' "$CINIT" || fail "Reference anchor missing"
grep -q 'IRIS_26432_STACK_SIZE_INVARIANT_REFERENCE_ROBUSTNESS' "$CACC" || fail "Scalable robustness missing"
grep -q 'robustReferenceAgreement' "$CACC" || fail "Post-warp residual missing"
grep -q 'orientationAgreement' "$CACC" || fail "Edge orientation gate missing"
grep -q 'perFrameCap=mix(0.72,0.11,edgeStrength)' "$CACC" || fail "Per-frame cap missing"
grep -q 'referenceCeiling=referenceAnchor\*1.70' "$CACC" || fail "Reference authority cap missing"
grep -q 'vec4(newSupport,referenceAnchor)' "$CACC" || fail "Reference anchor persistence missing"

grep -q 'IRIS_26432_TRUE_V2_EXTENDED_LINEAR_GAINMAP' "$CGM" || fail "True gainmap shader missing"
grep -q 'highlightAuthority=smoothstep(1.00,1.06,hdrY)' "$CGM" || fail "Highlight-only gain missing"
grep -q 'float ratio=mix(1.0,physicalRatio,highlightAuthority)' "$CGM" || fail "Unity body gain missing"
grep -q 'hdrExposureScale' "$CGM" || fail "Shared HDR exposure scale missing"
grep -q 'IRIS_26432_MOTION_V2_TRUE_ULTRAHDR' "$CUHDR" || fail "V2 UltraHDR helper missing"
grep -q 'setDisplayRatioForFullHdr(safeMax)' "$CUHDR" || fail "Display capacity metadata missing"
grep -q 'IRIS_26432_TRUE_V2_ULTRAHDR_ATTACH' "$CPOST" || fail "Post gainmap attachment missing"
grep -q 'saveBitmapAsJPGMotionV2' "$CHDRX" || fail "Motion JPEG route missing"
grep -q 'saveBitmapAsJPGMotionV2' "$CIMG" || fail "Motion compressor missing"

[[ "$(sha "$OLDUHDR")" == "$OLDUHDR_HASH" ]] || fail "Photo/Night UltraHdrSaver changed"
[[ "$(grep -c 'UltraHdrSaver.save' "$CIMG")" -eq "$(grep -c 'UltraHdrSaver.save' "$IMAGESAVER")" ]] || \
  fail "Photo/Night generic Ultra HDR routing changed"

grep -q '^VERSION_NAME=0\.9726432$' "$CV" || fail "Candidate version name wrong"
grep -q '^VERSION_BUILD=26432$' "$CV" || fail "Candidate build wrong"

echo "candidate/source validation PASS"

echo "=== GATE 3: GLSL LEXICAL + REAL COMPILER VALIDATION ==="
if ! command -v glslangValidator >/dev/null 2>&1; then
  command -v sudo >/dev/null 2>&1 || fail "glslangValidator missing and sudo unavailable"
  sudo apt-get update
  sudo apt-get install -y glslang-tools
fi

LEX="$SAFETY/validate_26432_glsl.py"
cat > "$LEX" <<'PYLEX'
from pathlib import Path
import re,sys
def clean(s):
    s=re.sub(r'/\*.*?\*/',' ',s,flags=re.S)
    s=re.sub(r'//.*',' ',s)
    return s
for name in sys.argv[1:]:
    p=Path(name); t=p.read_text(); c=clean(t)
    if re.search(r'(?m)^\s*#version\b',t):
        raise SystemExit('FAIL: asset owns #version: '+str(p))
    toks=set(re.findall(r'\b[A-Za-z_][A-Za-z0-9_]*\b',c))
    if 'coherent' in toks:
        raise SystemExit('FAIL: known reserved token coherent: '+str(p))
print('LEXICAL GLSL VALIDATION PASS')
PYLEX
python3 "$LEX" "$CINIT" "$CACC" "$CRG" "$CGM" "$COLORG" "$DENOISEG"

COMP_WRAP="$SAFETY/wrap_compute.py"
cat > "$COMP_WRAP" <<'PYCOMP'
from pathlib import Path
import re,sys
s=Path(sys.argv[1]).read_text()
s=re.sub(r'(?m)^#define\s+LAYOUT\s+//\s*\nLAYOUT\s*\n','',s,count=1)
Path(sys.argv[2]).write_text(
    '#version 310 es\nlayout(local_size_x=8, local_size_y=8, local_size_z=1) in;\n'+s)
PYCOMP

FRAG_WRAP="$SAFETY/wrap_frag.py"
cat > "$FRAG_WRAP" <<'PYFRAG'
from pathlib import Path
import sys
Path(sys.argv[2]).write_text('#version 310 es\n'+Path(sys.argv[1]).read_text())
PYFRAG

GLSLLOG="$SAFETY/glslang_26432.txt"
{
  python3 "$COMP_WRAP" "$CINIT" "$SAFETY/direct_init.comp"
  python3 "$COMP_WRAP" "$CACC" "$SAFETY/direct_acc.comp"
  python3 "$FRAG_WRAP" "$CRG" "$SAFETY/render.frag"
  python3 "$FRAG_WRAP" "$CGM" "$SAFETY/gainmap.frag"
  python3 "$FRAG_WRAP" "$COLORG" "$SAFETY/color_preserved.frag"
  python3 "$FRAG_WRAP" "$DENOISEG" "$SAFETY/denoise_preserved.frag"

  echo "=== direct init 26432 ==="; glslangValidator -S comp "$SAFETY/direct_init.comp"
  echo "=== direct accumulator 26432 ==="; glslangValidator -S comp "$SAFETY/direct_acc.comp"
  echo "=== render 26432 ==="; glslangValidator -S frag "$SAFETY/render.frag"
  echo "=== gainmap 26432 ==="; glslangValidator -S frag "$SAFETY/gainmap.frag"
  echo "=== protected color 26431 ==="; glslangValidator -S frag "$SAFETY/color_preserved.frag"
  echo "=== protected denoise 26431 ==="; glslangValidator -S frag "$SAFETY/denoise_preserved.frag"
} 2>&1 | tee "$GLSLLOG"
echo "GLSL COMPILER VALIDATION PASS"

echo "=== GATE 4: JAVA/API STATIC CONTRACT VALIDATION ==="
JVAL="$SAFETY/validate_26432_java.py"
cat > "$JVAL" <<'PYJAVA'
from pathlib import Path
import sys
r=Path(sys.argv[1]).read_text()
p=Path(sys.argv[2]).read_text()
u=Path(sys.argv[3]).read_text()
h=Path(sys.argv[4]).read_text()
i=Path(sys.argv[5]).read_text()
for x in (
    'OUTPUT_EXPOSURE_SCALE = 0.80f',
    'motionV2GainMapBitmap',
    'motionV2GainMapMaxRatio',
    'Bitmap.Config.ALPHA_8',
    'textureBuffer(readFormat, true)',
):
    if x not in r: raise SystemExit('FAIL: render contract missing '+x)
for x in ('MotionV2UltraHdr.attach','motionV2GainMapBitmap','IRIS_26432_TRUE_V2_ULTRAHDR_ATTACH'):
    if x not in p: raise SystemExit('FAIL: PostPipeline contract missing '+x)
for x in (
    'new Gainmap(oriented)','setRatioMin','setRatioMax','setGamma',
    'setEpsilonSdr','setEpsilonHdr','setMinDisplayRatioForHdrTransition',
    'setDisplayRatioForFullHdr','sdrBase.setGainmap(gainmap)'
